async function run() {
  // ---------- #3 get_function_details silent drop ----------
  const lf = await list_functions();
  const lfShape = typeof lf === "object" && !Array.isArray(lf)
    ? "obj(keys=" + Object.keys(lf).slice(0, 20).join(",") + ")"
    : Array.isArray(lf) ? "array(len=" + lf.length + ")" : typeof lf;
  const sample = Array.isArray(lf) ? lf.slice(0, 3) : (lf && Object.keys(lf)[0] ? [Object.keys(lf)[0]] : []);

  let gd, gdErr = null, gdShape = null;
  const bogus = "Bogus.nonexistent", real = "Developer.shell";
  try { gd = await get_function_details([bogus, real]); }
  catch (e) { gdErr = String(e && e.message ? e.message : e); }
  const gdList = gd && Array.isArray(gd) ? gd : null;
  gdShape = gdList ? "array(len=" + gdList.length + ", names=" + gdList.map(x => x && (x.name || x.id || JSON.stringify(x).slice(0, 60))).join(" | ") + ")"
    : (gd && !gdErr ? "obj(keys=" + Object.keys(gd).slice(0, 30).join(",") + ")" : null);

  // ---------- #5 import / fs / fetch / require / process / Deno ----------
  const r5 = {};
  try { const m: any = await import("fs"); r5.fs_import = "resolved:" + (m && Object.keys(m).slice(0, 5).join(",")); }
  catch (e: any) { r5.fs_import = "ERROR:" + (e && e.message ? e.message : e); }
  try { r5.fetch_type = typeof fetch; } catch (e: any) { r5.fetch_type = "ERROR:" + String(e && e.message ? e.message : e); }
  try { r5.require_type = typeof (globalThis as any).require; } catch (e: any) { r5.require_type = "ERROR:" + String(e && e.message ? e.message : e); }
  try { r5.process_exists = typeof (globalThis as any).process; } catch (e: any) { r5.process_exists = "ERROR:" + String(e && e.message ? e.message : e); }
  try { r5.deno_exists = typeof (globalThis as any).Deno; } catch (e: any) { r5.deno_exists = "ERROR:" + String(e && e.message ? e.message : e); }

  return {
    #3_lf_shape: lfShape,
    #3_sample: JSON.stringify(sample).slice(0, 400),
    #3_gd_shape: gdShape,
    #3_gd_err: gdErr,
    #3_gd_full: JSON.stringify(gd).slice(0, 2000),
    #5: r5,
  };
}

