  const sample = Array.isArray(lf) ? lf.slice(0, 3) : (lf && typeof lf === "object" ? [Object.keys(lf)[0]] : []);

  let gd: any = null, gdErr: string | null = null;
  const bogus = "Bogus.nonexistent", real = "Developer.shell";
  try { gd = await get_function_details([bogus, real]); }
  catch (e: any) { gdErr = String(e && e.message ? e.message : e); }
  const gdList = gd && Array.isArray(gd) ? gd : null;
  const gdShape = gdList
    ? "array(len=" + gdList.length + ", names=" + gdList.map((x: any) => x && (x.name || x.id || JSON.stringify(x).slice(0, 50))).join(" | ") + ")"
    : (gd && typeof gd === "object" ? "obj(keys=" + Object.keys(gd).slice(0, 30).join(",") + ")" : "null");

  // ---------- #5 import/fs/fetch/require/process/Deno ----------
  const r5: Record<string, any> = {};
  try { const m: any = await import("fs"); r5.fs_import = "resolved(" + (m && Object.keys(m).length + " keys)"; }
  catch (e: any) { r5.fs_import = "ERROR:" + (e && e.message ? e.message : e); }
  try { r5.fetch_type = typeof (globalThis as any).fetch; } catch (e: any) { r5.fetch_type = "ERROR:" + String(e); }
  try { r5.require_type = typeof (globalThis as any).require; } catch (e: any) { r5.require_type = "ERROR:" + String(e); }
  try { r5.process_exists = typeof (globalThis as any).process; } catch (e: any) { r5.process_exists = "ERROR:" + String(e); }
  try { r5.deno_exists = typeof (globalThis as any).Deno; } catch (e: any) { r5.deno_exists = "ERROR:" + String(e); }

  // ---------- #7 read binary PDF silently -> text ----------
  let readOut: any = null, readErr: string | null = null, readShape: string | null = null;
  try {
    readOut = await read({ path: "/Users/billtse/.agnes/temporary/2026-10-12/20261012_25/work/fake.pdf" });
    if (typeof readOut === "string") readShape = "string(len=" + readOut.length + ", head=" + JSON.stringify(readOut.slice(0, 60)) + ")";
    else if (readOut && typeof readOut === "object") readShape = "obj(keys=" + Object.keys(readOut).join(",") + ", preview=" + JSON.stringify(readOut).slice(0, 200) + ")";
    else readShape = String(typeof readOut);
  } catch (e: any) { readErr = String(e && e.message ? e.message : e); }

  return {
    t3: { lf_shape: lfShape, sample: JSON.stringify(sample).slice(0, 300), gd_shape: gdShape, gd_err: gdErr, gd_full: JSON.stringify(gd).slice(0, 1500) },
    t5: r5,
    t7: { shape: readShape, err: readErr },
  };
}

