/**
 *
 */
namespace Developer {
  export type ShellInput = {
    command: string;
    /**
     * Request network access for this invocation; requires tool approval or Full access (Auto) mode.
     */
    network?: boolean | undefined;
    /**
     * Maximum time in seconds to allow the command to run before it is killed.
     * If omitted, defaults to DEFAULT_EXTENSION_TIMEOUT.
     */
    timeout_secs?: number | null | undefined;
  };

  export type ShellOutput = {
    stdout: string;

    stderr: string;
    /**
     * Process exit code. 0 indicates success, non-zero indicates failure.
     * Absent if the process was terminated by a signal.
     */
    exit_code?: number | null | undefined;
    /**
     * Unix signal that terminated the process.
     */
    termination_signal?: number | null | undefined;
    /**
     * True if the command was killed because it exceeded the timeout.
     */
    timed_out?: boolean | undefined;
    /**
     * True if the command was killed because the active turn was cancelled.
     */
    cancelled?: boolean | undefined;
    /**
     * True if output collection was cut short after the shell exited.
     */
    output_truncated?: boolean | undefined;
    /**
     * Error reported by output collection after process exit.
     */
    output_collection_error?: string | null | undefined;
  };

  /**
   * Execute a shell command in the current dir. Commands run under `bash` (set AGNES_SHELL to override) - write command strings in that shell's syntax, which may differ from the user's interactive terminal. This platform does not expose the Windows `shell` selection parameter. Honor any user-requested interpreter/version constraints; report an unavailable or incompatible environment instead of silently switching interpreters. Inspect stderr and verify expected results even when exit_code is zero. Returns stdout and stderr as separate fields. Each stream is limited to 2000 lines; longer outputs are saved to a temporary file. Ordinary shell commands have network access disabled by the OS sandbox by default. Full access (Auto) mode or approval of this shell call enables network access for the invocation and its descendants. In other modes, set network=true to request network access for a call that would otherwise run without approval. Existing file restrictions remain in place. Managed CLI invocations retain their own execution policy. Hidden credential files or environment variables do not prove the host has no credentials.
   */
  export async function shell(input: ShellInput): Promise<ShellOutput>
}

function.description:
show pie or donut charts for categorical data visualization.
Supports one or more charts in a grid layout.
The `data` field must always be an array; pass a single-element array for one chart.

Each chart object must contain:
- values: Array of numbers OR objects with 'label' and 'value'
- type: Optional 'doughnut' (default) or 'pie'
- title: Optional chart title
- labels: Optional array of labels (required when values are plain numbers)

Example single chart (labeled values):
[
  {
    "values": [
      {"label": "Marketing", "value": 25000},
      {"label": "Development", "value": 35000}
    ],
    "title": "Budget"
  }
]

Example single chart (parallel arrays):
[
  {
    "values": [45000, 38000],
    "labels": ["Product A", "Product B"],
    "type": "pie"
  }
]

Example multiple charts (array of chart objects):
[
  {"values": [60, 40], "labels": ["Yes", "No"], "title": "Q1"},
  {"values": [75, 25], "labels": ["Yes", "No"], "title": "Q2"}
]

show a Mermaid diagram from Mermaid syntax

Provide the Mermaid code as a string. Supports flowcharts, sequence diagrams, Gantt charts, etc.

Example:
graph TD;
    A-->B;
    A-->C;
    B-->D;
    C-->D;

show a radar chart (spider chart) for multi-dimensional data comparison

The data must contain:
- labels: Array of strings representing the dimensions/axes
- datasets: Array of dataset objects with 'label' and 'data' properties

Example:
{
  "labels": ["Speed", "Strength", "Endurance", "Agility", "Intelligence"],
  "datasets": [
    {
      "label": "Player 1",
      "data": [85, 70, 90, 75, 80]
    },
    {
      "label": "Player 2",
      "data": [75, 85, 80, 90, 70]
    }
  ]
}

show a Sankey diagram from flow data
The data must contain:
- nodes: Array of objects with 'name' and optional 'category' properties
- links: Array of objects with 'source', 'target', and 'value' properties

IMPORTANT: Links must NOT form cycles (e.g. A→B and B→A). Sankey diagrams are
directional acyclic flows. If the data has circular relationships, restructure
them so flow moves in one direction (e.g. add a separate node like "Re-signed"
instead of linking back to an earlier node).

Example:
{
  "nodes": [
    {"name": "Source A", "category": "source"},
    {"name": "Target B", "category": "target"}
  ],
  "links": [
    {"source": "Source A", "target": "Target B", "value": 100}
  ]
}

show a treemap visualization for hierarchical data with proportional area representation as boxes

The data should be a hierarchical structure with:
- name: Name of the node (required)
- value: Numeric value for leaf nodes (optional for parent nodes)
- children: Array of child nodes (optional)
- category: Category for coloring (optional)

Example:
{
  "name": "Root",
  "children": [
    {
      "name": "Group A",
      "children": [
        {"name": "Item 1", "value": 100, "category": "Type1"},
        {"name": "Item 2", "value": 200, "category": "Type2"}
      ]
    },
    {"name": "Item 3", "value": 150, "category": "Type1"}
  ]
}

show interactive line, scatter, or bar charts

Required: type ('line', 'scatter', or 'bar'), datasets array
Optional: labels, title, subtitle, xAxisLabel, yAxisLabel, options

Example:
{
  "type": "line",
  "title": "Monthly Sales",
  "labels": ["Jan", "Feb", "Mar"],
  "datasets": [
    {"label": "Product A", "data": [65, 59, 80]}
  ]
}

